using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;
namespace ParkingLotEnvironment.CloudPilot { public static class WholeMapFinish {
 const string W="Assets/ParkingLotEnvironment/CloudPilot/WholeMapFinish20261105",Source="Assets/ParkingLotEnvironment/CloudPilot/PorterReference20261105/PorterReferenceParkingLot.unity";
 static string output;static GameObject root;static Camera cam;static double start;static int frame;static Vector3 eye;static Quaternion facing;static readonly List<string> changes=new List<string>();
 public static void RoofBake(){try{var args=Environment.GetCommandLineArgs();output=args[Array.IndexOf(args,"-collabOutput")+1];EditorSceneManager.OpenScene(W+"/WholeMapReview.unity");root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");cam=root.GetComponentInChildren<Camera>();cam.enabled=true;int count=RoofRepair.Apply(root);File.AppendAllText(output+"/changes.txt","\nSeparated roof faces on "+count+" building meshes; existing facade texture and all UVs retained.\n");foreach(var probe in root.GetComponentsInChildren<ReflectionProbe>(true))probe.enabled=false;AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());start=EditorApplication.timeSinceStartup;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Roof bake refused");}catch(Exception e){Fail(e);}}
 public static void Build(){try{var args=Environment.GetCommandLineArgs();output=args[Array.IndexOf(args,"-collabOutput")+1];Directory.CreateDirectory(output);if(File.Exists(W+"/WholeMapReview.unity"))throw new Exception("Review already exists");EditorSceneManager.OpenScene(Source);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");cam=root.GetComponentInChildren<Camera>();eye=cam.transform.position;facing=cam.transform.rotation;cam.enabled=false;Render("before.png",new Vector3(.7f,2.8f,-17.5f),new Vector3(.7f,1.2f,-6.7f));
 var layout=root.GetComponentInChildren<ParkingLotEnvironment.Training.ParkingTrainingLayout>();var cache=new Dictionary<string,Material>();int count=0;
 foreach(var r in root.GetComponentsInChildren<MeshRenderer>()) {bool vehicle=r.transform.IsChildOf(layout.transform)&&r.GetComponentsInParent<Transform>().Any(t=>t.name.StartsWith("Parked_"));var slots=r.sharedMaterials;for(int j=0;j<slots.Length;j++){var src=slots[j];if(!src)continue;string n=src.name.ToLowerInvariant(),sn=src.shader.name.ToLowerInvariant();string kind=null;
 if(vehicle){if(n.Contains("glass")||sn.Contains("glass"))kind="glass";else if(n.Contains("paint")||n.Contains("_blue")||n.Contains("deepblue"))kind="paint";else if(n.Contains("rubber")||n.Contains("tire")||n.Contains("tyre"))kind="rubber";else if(n.Contains("wheel")||n.Contains("chrome"))kind="metal";else if(n.Contains("trim"))kind="trim";}
 else if(n.Contains("concrete")||n.Contains("coping"))kind="concrete";
 else if((r.transform.IsChildOf(root.transform.Find("AG_Photorealistic3D_Assets"))||r.transform.IsChildOf(root.transform.Find("ParkingContext_ApprovedKitExtension")))&&src.HasProperty("_MainTex")&&src.GetTexture("_MainTex")&&src.HasProperty("_Color"))kind="building";
 if(kind==null)continue;string key=src.GetInstanceID()+"_"+kind+(kind=="building"?"_"+Mathf.RoundToInt(r.bounds.center.x/8):"");if(!cache.TryGetValue(key,out var m)){m=new Material(src);m.name="Review_"+cache.Count+"_"+kind;
 if(kind=="glass"){m.shader=Shader.Find("ParkingLot/WholeMap/Glazing");m.color=new Color(.035f,.046f,.052f,1);m.SetFloat("_Glossiness",.94f);m.shaderKeywords=new string[0];m.renderQueue=-1;}
 if(kind=="paint"){m.SetFloat("_Glossiness",.68f);m.SetFloat("_Metallic",.12f);if(m.HasProperty("_Color")){Color c=m.color;if(c.maxColorComponent<.13f)c*=1.45f;if(n.Contains("blue")||n.Contains("deepblue"))c=new Color(.105f,.17f,.24f,1);c.a=1;m.color=c;}}
 if(kind=="rubber"){m.color=new Color(.075f,.078f,.08f);m.SetFloat("_Metallic",0);m.SetFloat("_Glossiness",.2f);}
 if(kind=="metal"){m.SetFloat("_Glossiness",.6f);m.SetFloat("_Metallic",.75f);}
 if(kind=="trim"){m.SetFloat("_Glossiness",.24f);m.SetFloat("_Metallic",0);}
 if(kind=="concrete"){if(n.Contains("castconcrete")){m.shader=Shader.Find("ParkingLot/WholeMap/Concrete");m.color=new Color(.53f,.52f,.485f);}else if(m.HasProperty("_Glossiness"))m.SetFloat("_Glossiness",.12f);}
 if(kind=="building"){float v=.94f+.07f*(.5f+.5f*Mathf.Sin(r.bounds.center.x*.77f));m.color*=v;if(m.HasProperty("_Glossiness"))m.SetFloat("_Glossiness",Mathf.Min(m.GetFloat("_Glossiness"),.28f));}
 AssetDatabase.CreateAsset(m,W+"/"+m.name+".mat");cache[key]=m;changes.Add(src.name+" -> "+m.name);}
 slots[j]=m;count++;}r.sharedMaterials=slots;if(vehicle){r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;r.receiveShadows=true;r.shadowCastingMode=ShadowCastingMode.On;}}
 changes.Add("Changed material slots="+count+"; asphalt textures/layout/parking bays and original scene preserved. No photo training, no generated image substitute.");
 foreach(var p in root.GetComponentsInChildren<ReflectionProbe>(true))p.enabled=false;AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),W+"/WholeMapReview.unity");File.WriteAllLines(output+"/changes.txt",changes);start=EditorApplication.timeSinceStartup;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Bake refused");}catch(Exception e){Fail(e);}}
 static void BakeTick(){try{if(EditorApplication.timeSinceStartup-start>1500){Lightmapping.Cancel();throw new Exception("Bake timed out");}if(EditorApplication.timeSinceStartup-start<5||Lightmapping.isRunning)return;EditorApplication.update-=BakeTick;int i=0;foreach(var p in root.GetComponentsInChildren<ReflectionProbe>(true)){p.enabled=true;p.boxProjection=true;p.resolution=512;p.hdr=true;p.mode=ReflectionProbeMode.Baked;p.customBakedTexture=null;string path=W+"/Reflection"+(i++)+".exr";if(!Lightmapping.BakeReflectionProbe(p,path))throw new Exception("Probe failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);p.mode=ReflectionProbeMode.Custom;p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);EditorUtility.SetDirty(p);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());File.WriteAllText(output+"/bake.txt","lightmaps="+LightmapSettings.lightmaps.Length+"; box probes="+i+"; seconds="+(EditorApplication.timeSinceStartup-start));frame=0;EditorApplication.update+=CaptureTick;}catch(Exception e){Fail(e);}}
 static void CaptureTick(){try{if(frame==0)Render("overview.png",new Vector3(.7f,2.8f,-17.5f),new Vector3(.7f,1.2f,-6.7f));else if(frame==1)Render("vehicles.png",new Vector3(-.1f,1.55f,-15.3f),new Vector3(-5.1f,1,-13.5f));else if(frame==2)Render("porter.png",new Vector3(-.3f,1.75f,-7),new Vector3(-5,1,-4.5f));else if(frame==3)Render("aerial.png",new Vector3(23,29,-35),new Vector3(0,1,-4));else if(frame==4)Render("entrance.png",new Vector3(.7f,3.6f,-33),new Vector3(.7f,2.1f,-20));else if(frame==5)Render("first-person.png",new Vector3(.7f,1.65f,-17.5f),new Vector3(.7f,1.65f,-6.7f));else{EditorApplication.update-=CaptureTick;File.WriteAllText(output+"/complete.txt","Full bake and five native 2560x1440 Unity captures complete. Candidate only; original scene unchanged.");EditorApplication.Exit(0);return;}frame++;}catch(Exception e){Fail(e);}}
 static void Render(string name,Vector3 p,Vector3 at){var rt=new RenderTexture(2560,1440,24,RenderTextureFormat.ARGBHalf);var prev=RenderTexture.active;var target=cam.targetTexture;var pos=cam.transform.position;var rot=cam.transform.rotation;try{rt.Create();cam.targetTexture=rt;cam.transform.SetPositionAndRotation(p,Quaternion.LookRotation(at-p));cam.Render();RenderTexture.active=rt;var tex=new Texture2D(2560,1440,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,2560,1440),0,0);tex.Apply();File.WriteAllBytes(output+"/"+name,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{cam.transform.SetPositionAndRotation(pos,rot);cam.targetTexture=target;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 static void Fail(Exception e){EditorApplication.update-=BakeTick;EditorApplication.update-=CaptureTick;Debug.LogException(e);if(output!=null)File.WriteAllText(output+"/FAILED.txt",e.ToString());EditorApplication.Exit(1);}
}}
